def _walk(offsets, init, lr, x):
    total = init
    unpack = struct.unpack_from
    for start, count in offsets:
        node = 0
        while True:
            off = start + node * _NS
            feat, thresh, left, right, val = unpack(_FMT, _DATA, off)
            if left == -1:  # leaf
                total += lr * val
                break
            node = left if x[feat] <= thresh else right
    return total

def score(x):
    """Return predicted minutes remaining for feature vector x (list of 17 floats).

    The primary ensemble predicts log1p(minutes) (heavy-tailed target) and is
    inverted here.  When _BLEND is set, a raw-minutes ensemble is blended in on
    the T_remaining feature: raw far from target (long-horizon absolute
    estimates), log near target (endgame / relative accuracy)."""
    near = _walk(_OFFSETS, _INIT, _LR, x)
    if _LOG:
        near = math.expm1(near)
    if not _BLEND:
        return near
    far = _walk(_OFFSETS_FAR, _INIT_FAR, _LR_FAR, x)
    t = (_T_FAR - x[_I_TREM]) / (_T_FAR - _T_NEAR)
    t = 0.0 if t < 0.0 else 1.0 if t > 1.0 else t
    w = t * t * (3.0 - 2.0 * t)   # smoothstep toward the log model near target
    return (1.0 - w) * far + w * near
